using System;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;
namespace FashionFit.Editor {
 public static class LayeredGarmentVerification {
  [Serializable] sealed class Result {public string status="passed",scope="Editor, actual hand proximity selection and Touch-state injection; not physical HMD";public int checks,exceptions,contactExports;public bool wornHatPatch,hatDetach,twoHandCloth,layerIsolation,persistentDesign,frontLift,recovery,shoulderCoverage;public bool mainShirtGrip,materialContrast;public float cottonDisplacement,feltDisplacement;public float hatOffset,shirtOffset,liftM,recoveryError,initialError,maxPanelStretch;public double maxAoDaiMs;}
  static FashionFitApp app;static Result result;static string folder;static void Check(bool ok,string label){result.checks++;if(!ok)throw new Exception(label);}static void Log(string a,string b,LogType type){if(type==LogType.Exception||type==LogType.Error)result.exceptions++;}
  public static void RepairIvory(){GameObject root=null;try{root=new GameObject("Repair Ivory authored assets");app=root.AddComponent<FashionFitApp>();typeof(FashionFitApp).GetMethod("Start",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(app,null);if(!app.Ready)throw new Exception(app.FatalError);for(int gender=0;gender<2;gender++){string stem="Assets/Resources/PoseWardrobe/"+(gender==0?"Female":"Male")+"05";var asset=AssetDatabase.LoadAssetAtPath<PoseOutfitAsset>(stem+".asset");var body=app.PoseStudio.Rigs[gender].Avatar;var old=asset.mesh;var shirt=FittedGarmentGeometry.Shell(body,false,false);float waist=body.BodyMesh.bounds.max.y*.60f;var v=new List<Vector3>(old.vertices);var uv=new List<Vector2>(old.uv);var weights=new List<BoneWeight>(old.boneWeights);var lower=new List<int>();var oldV=old.vertices;var faces=old.GetTriangles(0);for(int i=0;i<faces.Length;i+=3)if(Mathf.Min(oldV[faces[i]].y,Mathf.Min(oldV[faces[i+1]].y,oldV[faces[i+2]].y))<waist-.04f)lower.AddRange(new[]{faces[i],faces[i+1],faces[i+2]});int offset=v.Count;v.AddRange(shirt.vertices);uv.AddRange(shirt.uv);weights.AddRange(shirt.boneWeights);int[] upper=shirt.triangles;for(int i=0;i<upper.Length;i++)upper[i]+=offset;var remap=new Dictionary<int,int>();var compactV=new List<Vector3>();var compactUV=new List<Vector2>();var compactW=new List<BoneWeight>();Action<int[]> compact=indices=>{for(int k=0;k<indices.Length;k++){int original=indices[k];if(!remap.TryGetValue(original,out int id)){id=compactV.Count;remap.Add(original,id);compactV.Add(v[original]);compactUV.Add(uv[original]);compactW.Add(weights[original]);}indices[k]=id;}};int[] lowerArray=lower.ToArray();compact(lowerArray);compact(upper);lower=new List<int>(lowerArray);v=compactV;uv=compactUV;weights=compactW;
var mesh=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,name="Repaired Ivory shoulders and short sleeves"};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.boneWeights=weights.ToArray();mesh.bindposes=body.GarmentBindposes;mesh.subMeshCount=2;mesh.SetTriangles(lower,0);mesh.SetTriangles(upper,1);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();EditorUtility.CopySerialized(mesh,asset.mesh);EditorUtility.SetDirty(asset.mesh);var fabric=new Material(Resources.Load<Shader>("Runway/DressFabric")){name="Ivory repaired cotton"};fabric.SetColor("_Color",new Color(.82f,.78f,.66f));fabric.SetFloat("_Glossiness",.18f);string path=stem+"_RepairedTop.mat";var previous=AssetDatabase.LoadAssetAtPath<Material>(path);if(previous){EditorUtility.CopySerialized(fabric,previous);UnityEngine.Object.DestroyImmediate(fabric);}else{AssetDatabase.CreateAsset(fabric,path);previous=fabric;}asset.materials=new[]{asset.materials[0],previous};EditorUtility.SetDirty(asset);UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(shirt);}AssetDatabase.SaveAssets();UnityEngine.Object.DestroyImmediate(root);EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);if(root)UnityEngine.Object.DestroyImmediate(root);EditorApplication.Exit(1);}}
  public static void RunBatch(){GameObject root=null;var mode=Physics.simulationMode;folder=Path.GetFullPath("Verification/LayeredGarment");Directory.CreateDirectory(folder+"/Contact");result=new Result();Application.logMessageReceived+=Log;try{Physics.simulationMode=SimulationMode.Script;root=new GameObject("Layered garment actual picking QA");app=root.AddComponent<FashionFitApp>();typeof(FashionFitApp).GetMethod("Start",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(app,null);Check(app.Ready,app.FatalError);typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,true);typeof(RunwayPlayer).GetProperty("HeadTracked").SetValue(app.Player,true);app.PoseStudio.SetHandles(false);app.Player.EnsureHands();var hands=app.Player.Hands;Check(hands,"Hands missing");
   // Worn hat must deform while staying on its own head. Acquisition goes through
   // the real hand overlap/picking code, not directly through target.TryAcquire.
   app.Showroom.SelectOutfitTarget(1);app.Showroom.WearHat(0);var hat=app.Showroom.Hats[0];Vector3[] hv=hat.Elastic.MeshAt(0).vertices;int hi=0;for(int i=1;i<hv.Length;i++)if(hv[i].z>hv[hi].z)hi=i;Vector3 hp=hat.transform.TransformPoint(hv[hi]);Grip(hands,0,hp,true);Check(hands.HeldBy(0)&&hands.HeldBy(0).IsWornHat,"Actual hand did not select equipped hat: "+(hands.HeldBy(0)?hands.HeldBy(0).DisplayName:"none"));for(int i=0;i<70;i++){hands.Step(0,true,hp+Vector3.up*.11f,Quaternion.identity,1,0,1f/60);hat.Elastic.Step(1f/60);}result.hatOffset=hat.Elastic.MaximumOffset;result.wornHatPatch=hat.IsEquipped&&!hat.IsHeld&&hat.Elastic.GrabCount==1&&result.hatOffset>.02f;Check(result.wornHatPatch,"Equipped hat did not deform in place");app.Showroom.SelectOutfitTarget(0);app.MaterialLab.SelectProfile(1);Check(hat.Elastic.Material==MembraneMaterial.Presets[1]&&app.Wardrobe.ActiveMembraneMaterial==null,"Material focus did not follow adjusted worn hat");app.MaterialLab.SelectProfile(0);hands.ReleaseAll(false);hat.Elastic.ResetShape();hp=hat.transform.TransformPoint(hat.Elastic.MeshAt(0).vertices[hi]);Grip(hands,0,hp,false);result.hatDetach=hat.IsHeld&&!hat.IsEquipped;Check(result.hatDetach,"Normal Grip did not detach hat");hands.ReleaseAll(true);hat.ReturnToDisplay();
   // Actual pose-shirt surface must beat the enclosing base selection volume.
   app.PoseStudio.Wear(0,5);var wear=app.PoseStudio.Wearables[0];Vector3 a=Chest(wear.Surface,-1),b=Chest(wear.Surface,1);Grip(hands,0,a,false);Grip(hands,1,b,false);result.twoHandCloth=hands.HeldCount==2&&wear.Surface.GrabCount==2;Check(result.twoHandCloth,"Hands selected base/joint instead of shirt");for(int i=0;i<80;i++){hands.Step(0,true,a+Vector3.forward*.12f+Vector3.up*.06f,Quaternion.identity,1,0,1f/60);hands.Step(1,true,b+Vector3.forward*.12f,Quaternion.identity,1,0,1f/60);wear.Step(1f/60);}result.shirtOffset=wear.Surface.MaximumOffset;Check(result.shirtOffset>.025f&&result.shirtOffset<.065f,"Pose shirt feels rigid/no response");hands.ReleaseAll(false);
   var shoulder=wear.Rig.Avatar.transform.TransformPoint(new Vector3(.17f,1.42f,0));result.shoulderCoverage=wear.Surface.Nearest(shoulder,.12f,out _);Check(result.shoulderCoverage,"Repaired shoulder still absent");
   result.cottonDisplacement=MaterialPull(wear,MembraneMaterial.Presets[0]);result.feltDisplacement=MaterialPull(wear,MembraneMaterial.Presets[2]);result.materialContrast=result.cottonDisplacement>result.feltDisplacement*1.15f;Check(result.materialContrast,"Cotton/felt have indistinguishable pull response");
   foreach(var profile in MembraneMaterial.Presets)Check(Mathf.Abs(profile.MembraneForce(.05f,Vector3.up)-profile.SheetWarp*.05f)<.001f,"Incorrect material SI tension");
   app.SetLook(5);var mainShirt=app.Model.GetComponentInChildren<InteractiveShirt>();var mainDriver=mainShirt.GetComponentInChildren<BodyBoundSurface>();Vector3 shirtPoint=Chest(mainShirt.Surface,-1);Grip(hands,0,shirtPoint,false);result.mainShirtGrip=hands.HeldBy(0)&&hands.HeldBy(0).Elastic==mainShirt.Surface;Check(result.mainShirtGrip,"Main mannequin shirt is not selected by near hand");for(int i=0;i<50;i++){hands.Step(0,true,shirtPoint+Vector3.forward*.12f,Quaternion.identity,1,0,1f/60);mainDriver.Step(1f/60);}Check(mainShirt.Surface.MaximumOffset>.025f&&mainShirt.Surface.MaximumOffset<.065f,"Main shirt has no pull response");hands.ReleaseAll(false);
   // Ao dai on all three mannequin targets, full bodies kept for exports.
   for(int target=0;target<3;target++){app.Showroom.SelectOutfitTarget(target);app.LayerLab.WearSelected();var ao=app.LayerLab.Current;Check(ao.Front&&ao.Back&&ao.Pants&&ao.Bodice,"Ao dai part missing");for(int i=0;i<150;i++){ao.Bodice.Step(1f/60);ao.Pants.Step(1f/60);ao.StepSimulation(1f/60);}Export(ao,"Target"+target+"_Rest");Debug.Log("LAYERED_TARGET "+target+" ms="+ao.Milliseconds);result.maxAoDaiMs=Math.Max(result.maxAoDaiMs,ao.Milliseconds);}
   app.Showroom.SelectOutfitTarget(1);var outfit=app.LayerLab.Current;outfit.SelectLayer(1);int tip=outfit.Front.Positions.Length-10;Vector3 p=outfit.Front.transform.TransformPoint(outfit.Front.Positions[tip]);Vector3[] baseline=(Vector3[])outfit.Front.Positions.Clone();float startY=outfit.Front.Positions[tip].y;Grip(hands,0,p,false);Check(hands.HeldBy(0)&&hands.HeldBy(0).Panel==outfit.Front,"Front layer not grabbable through real hand path");Check(!outfit.Back.GetComponent<RunwayVRGrabTarget>().CanGrab,"Locked back layer still interactive");result.layerIsolation=true;var oldBackMaterial=outfit.Back.Material;outfit.SetMaterial(MembraneMaterial.Presets[0]);Check(outfit.Front.Material==MembraneMaterial.Presets[0]&&outfit.Back.Material==oldBackMaterial,"Changing front material changed locked back layer");outfit.SetMaterial(MembraneMaterial.Presets[1]);
   for(int i=0;i<120;i++){hands.Step(0,true,p+Vector3.up*.32f+Vector3.forward*.16f,Quaternion.identity,1,0,1f/60);outfit.StepSimulation(1f/60);}result.liftM=outfit.Front.Positions[tip].y-startY;result.frontLift=result.liftM>.12f;Check(result.frontLift,"Tail did not lift with the hand");result.initialError=Error(outfit.Front.Positions,baseline);result.maxPanelStretch=outfit.Front.MaxRatio;Export(outfit,"Female_Lift");hands.ReleaseAll(false);for(int i=0;i<420;i++)outfit.StepSimulation(1f/60);result.recoveryError=Error(outfit.Front.Positions,baseline);result.recovery=result.recoveryError<result.initialError*.70f;Check(result.recovery,"Tail did not recover after release");Export(outfit,"Female_Recovery");outfit.SetDesign(.90f,1.10f);for(int i=0;i<120;i++)outfit.StepSimulation(1f/60);result.persistentDesign=Mathf.Abs(outfit.LengthScale-.90f)<.001f&&Mathf.Abs(outfit.WidthScale-1.10f)<.001f;Check(result.persistentDesign,"Design dimensions did not persist");Export(outfit,"Female_Design");
   var avatar=outfit.Avatar;var leg=avatar.FindJoint("RightLeg");var thigh=avatar.FindJoint("RightUpLeg");var elbow=avatar.FindJoint("LeftForeArm");var r0=leg.localRotation;var r1=thigh.localRotation;var r2=elbow.localRotation;for(int i=1;i<=35;i++){float t=i/35f;leg.localRotation=r0*Quaternion.Euler(35*t,0,0);thigh.localRotation=r1*Quaternion.Euler(-20*t,0,0);elbow.localRotation=r2*Quaternion.Euler(0,0,35*t);outfit.Bodice.Step(1f/60);outfit.Pants.Step(1f/60);outfit.Wake();outfit.StepSimulation(1f/60);}Export(outfit,"Female_Pose");app.PoseStudio.ResetPose(0);outfit.Bodice.Step(1f/60);outfit.Pants.Step(1f/60);outfit.ResetDrape();for(int i=0;i<100;i++)outfit.StepSimulation(1f/60);
   hands.Hide();Capture();Check(result.exceptions==0,"Unity exceptions during layered test");Save();typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,false);UnityEngine.Object.DestroyImmediate(root);root=null;Physics.simulationMode=mode;EditorApplication.Exit(0);
  }catch(Exception e){result.status="failed";Save();File.WriteAllText(folder+"/failure.txt",e.ToString());Debug.LogException(e);Physics.simulationMode=mode;EditorApplication.Exit(1);}finally{Application.logMessageReceived-=Log;if(root){if(app&&app.Player)typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,false);UnityEngine.Object.DestroyImmediate(root);}Physics.simulationMode=mode;}}
  static void Grip(RunwayVRHands h,int side,Vector3 p,bool detach){Physics.SyncTransforms();h.Step(side,true,p,Quaternion.identity,0,detach?1:0,1f/60);h.Step(side,true,p,Quaternion.identity,1,detach?1:0,1f/60);}
  static Vector3 Chest(ElasticSurface surface,int side){var v=surface.MeshAt(0).vertices;int best=0;float d=float.PositiveInfinity;Vector3 wanted=new Vector3(side*.10f,1.28f,.16f);for(int i=0;i<v.Length;i++){float e=(v[i]-wanted).sqrMagnitude;if(e<d){d=e;best=i;}}return surface.transform.TransformPoint(v[best]);}
  static float MaterialPull(PoseWearable wear,MembraneMaterial material){var surface=wear.Surface;surface.SetMaterial(material);surface.ResetShape();wear.Step(1f/60);Vector3 p=Chest(surface,-1);Vector3[] baseline=surface.MeshAt(0).vertices;int index=0;float nearest=float.PositiveInfinity;for(int i=0;i<baseline.Length;i++){float d=Vector3.Distance(surface.transform.TransformPoint(baseline[i]),p);if(d<nearest){nearest=d;index=i;}}Check(surface.BeginGrip(0,p),"Material test grip failed");for(int i=0;i<60;i++){surface.MoveGrip(0,p+Vector3.forward*.32f);wear.Step(1f/60);}float result=Vector3.Distance(surface.MeshAt(0).vertices[index],baseline[index]);surface.EndGrip(0);surface.ResetShape();wear.Step(1f/60);return result;}
  static float Error(Vector3[] p,Vector3[] baseline){float e=0;for(int i=0;i<p.Length;i++)e+=(p[i]-baseline[i]).sqrMagnitude;return Mathf.Sqrt(e/p.Length);}
  static void Save(){File.WriteAllText(folder+"/verification.json",JsonUtility.ToJson(result,true));Debug.Log("LAYERED_QA "+JsonUtility.ToJson(result));}
  static void Export(LayeredAoDai ao,string name){var body=new Mesh();var avatar=ao.Avatar;var previous=avatar.Renderer.sharedMesh;avatar.Renderer.sharedMesh=avatar.BodyMesh;avatar.Renderer.BakeMesh(body);avatar.Renderer.sharedMesh=previous;using(var w=new BinaryWriter(File.Create(folder+"/Contact/"+name+".bin"))){w.Write(0x4c415931);Write(w,body.vertices,body.triangles);Write(w,ao.Bodice.Surface.MeshAt(0).vertices,ao.Bodice.Surface.MeshAt(0).triangles);Write(w,ao.Pants.Surface.MeshAt(0).vertices,ao.Pants.Surface.MeshAt(0).triangles);Write(w,ao.Front.Positions,ao.Front.Faces);Write(w,ao.Back.Positions,ao.Back.Faces);}UnityEngine.Object.DestroyImmediate(body);result.contactExports++;}
  static void Write(BinaryWriter w,Vector3[] p,int[] t){w.Write(p.Length);foreach(var v in p){w.Write(v.x);w.Write(v.y);w.Write(v.z);}w.Write(t.Length);foreach(int i in t)w.Write(i);}
  static void Capture(){var c=app.Player.View;c.rect=new Rect(0,0,1,1);c.transform.position=new Vector3(2.2f,1.55f,.90f);c.transform.LookAt(new Vector3(2.2f,1,-1.9f));var rt=new RenderTexture(1400,1100,24);var tex=new Texture2D(1400,1100,TextureFormat.RGB24,false);var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1400,1100),0,0);tex.Apply();File.WriteAllBytes(folder+"/AoDai.png",tex.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}}
 }
